 25	struct CudaTimingSession::Impl {
 26	    CudaTimingInfo info;
 27	    std::size_t size = 0, bytes = 0;
 28	    Key *host_input = nullptr, *host_output = nullptr, *input = nullptr, *output = nullptr;
 29	    void* workspace = nullptr;
 30	    cudaStream_t stream = nullptr;
 31	    std::array<cudaEvent_t, 4> events{};
 32	    bool closed = false;
 33	    ~Impl() noexcept {
 34	        if (stream) secondary(cudaStreamSynchronize(stream));
 35	        for (auto e : events) if (e) secondary(cudaEventDestroy(e));
 36	        if (workspace) secondary(cudaFree(workspace));
 37	        if (output) secondary(cudaFree(output));
 38	        if (input) secondary(cudaFree(input));
 39	        if (host_output) secondary(cudaFreeHost(host_output));
 40	        if (host_input) secondary(cudaFreeHost(host_input));
 41	        if (stream) secondary(cudaStreamDestroy(stream));
 42	    }
 43	    void init(std::size_t n, std::size_t memory_limit_mib) {
 44	        if (n > 1000000 || memory_limit_mib == 0 || memory_limit_mib > 65536)
 45	            throw std::invalid_argument("CUDA timing size/limit outside milestone bounds");
 46	        size = n; bytes = n * sizeof(Key);
 47	        const auto limit = static_cast<std::uint64_t>(memory_limit_mib) * 1024 * 1024;
 48	        if (bytes > limit / 5) throw std::invalid_argument("host payload budget exceeded");
 49	        checked(cudaGetDevice(&info.device), "get device");
 50	        cudaDeviceProp prop{};
 51	        checked(cudaGetDeviceProperties(&prop, info.device), "device properties");
 52	        info.device_name = prop.name; info.compute_major = prop.major; info.compute_minor = prop.minor;
 53	        info.device_memory_bytes = prop.totalGlobalMem;
 54	        checked(cudaRuntimeGetVersion(&info.runtime_version), "runtime version");
 55	        checked(cudaDriverGetVersion(&info.driver_version), "driver version");
 56	        if (size < 2) return;
 57	        std::size_t available = 0, total = 0;
 58	        checked(cudaMemGetInfo(&available, &total), "device free memory");
 59	        if (bytes > available / 4) throw std::runtime_error("device keys exceed half free memory");
 60	        checked(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking), "create private stream");
 61	        for (auto& event : events) checked(cudaEventCreate(&event), "create timing event");
 62	        checked(cudaMallocHost(reinterpret_cast<void**>(&host_input), bytes), "allocate pinned input");
 63	        checked(cudaMallocHost(reinterpret_cast<void**>(&host_output), bytes), "allocate pinned output");
 64	        checked(cudaMalloc(reinterpret_cast<void**>(&input), bytes), "allocate device input");
 65	        checked(cudaMalloc(reinterpret_cast<void**>(&output), bytes), "allocate device output");
 66	        checked(cub::DeviceRadixSort::SortKeys(nullptr, info.workspace_bytes, input, output,
 67	                static_cast<int>(size), 0, 32, stream), "workspace sizing");
 68	        if (2 * bytes > limit || info.workspace_bytes > limit - 2 * bytes ||
 69	            2 * bytes > available / 2 || info.workspace_bytes > available / 2 - 2 * bytes)
 70	            throw std::runtime_error("CUDA workspace exceeds device budget");
 71	        checked(cudaMalloc(&workspace, info.workspace_bytes ? info.workspace_bytes : 1), "allocate workspace");
 72	    }
 73	};
