 78	CudaTimingSample CudaTimingSession::sample(const Values& input, Values& output) {
 79	    auto& s = *impl_;
 80	    if (s.closed || input.size() != s.size || output.size() != s.size || &input == &output)
 81	        throw std::invalid_argument("invalid prepared CUDA timing buffers/session");
 82	    using Clock = std::chrono::steady_clock;
 83	    static_assert(Clock::is_steady, "monotonic host timer required");
 84	    CudaTimingSample result;
 85	    if (s.size < 2) {
 86	        const auto start = Clock::now();
 87	        if (s.size) output[0] = input[0];
 88	        const auto stop = Clock::now();
 89	        result.end_to_end_ns = static_cast<std::uint64_t>(
 90	            std::chrono::duration_cast<std::chrono::nanoseconds>(stop - start).count());
 91	        return result;
 92	    }
 93	    std::copy(input.begin(), input.end(), s.host_input);
 94	    checked(cudaStreamSynchronize(s.stream), "prior stream synchronize");
 95	    const auto start = Clock::now();
 96	    checked(cudaEventRecord(s.events[0], s.stream), "record H2D start");
 97	    checked(cudaMemcpyAsync(s.input, s.host_input, s.bytes, cudaMemcpyHostToDevice, s.stream), "H2D");
 98	    checked(cudaEventRecord(s.events[1], s.stream), "record sort start");
 99	    checked(cub::DeviceRadixSort::SortKeys(s.workspace, s.info.workspace_bytes, s.input, s.output,
100	            static_cast<int>(s.size), 0, 32, s.stream), "CUB SortKeys");
101	    checked(cudaGetLastError(), "CUB launch status");
102	    checked(cudaEventRecord(s.events[2], s.stream), "record D2H start");
103	    checked(cudaMemcpyAsync(s.host_output, s.output, s.bytes, cudaMemcpyDeviceToHost, s.stream), "D2H");
104	    checked(cudaEventRecord(s.events[3], s.stream), "record D2H stop");
105	    checked(cudaEventSynchronize(s.events[3]), "pipeline completion");
106	    const auto stop = Clock::now();
107	    const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(stop - start).count();
108	    if (elapsed < 0) throw std::runtime_error("negative host duration");
109	    result.end_to_end_ns = static_cast<std::uint64_t>(elapsed);
110	    std::array<double*, 3> metrics{{&result.h2d_ns, &result.device_sort_ns, &result.d2h_ns}};
111	    for (std::size_t i = 0; i < metrics.size(); ++i) {
112	        float ms = 0;
113	        checked(cudaEventElapsedTime(&ms, s.events[i], s.events[i + 1]), "event elapsed time");
114	        if (!std::isfinite(ms) || ms < 0) throw std::runtime_error("invalid event duration");
115	        *metrics[i] = static_cast<double>(ms) * 1000000.0;
116	    }
117	    std::copy(s.host_output, s.host_output + s.size, output.begin());
118	    return result;
119	}
120	void CudaTimingSession::close() {
121	    auto& s = *impl_;
122	    if (s.closed) return;
123	    if (s.stream) checked(cudaStreamSynchronize(s.stream), "close synchronize");
124	    for (auto& event : s.events) if (event) {
125	        const auto e = event; event = nullptr; checked(cudaEventDestroy(e), "destroy event");
126	    }
127	    auto release_device = [](auto*& pointer) {
128	        if (pointer) { auto* value = pointer; pointer = nullptr; checked(cudaFree(value), "free device buffer"); }
129	    };
130	    release_device(s.workspace); release_device(s.output); release_device(s.input);
131	    for (auto** p : {&s.host_output, &s.host_input})
132	        if (*p) { auto* value = *p; *p = nullptr; checked(cudaFreeHost(value), "free pinned buffer"); }
133	    if (s.stream) { const auto stream = s.stream; s.stream = nullptr; checked(cudaStreamDestroy(stream), "destroy stream"); }
134	    s.closed = true;
135	}
