 23	class DeviceBuffer {
 24	public:
 25	    explicit DeviceBuffer(std::size_t bytes) {
 26	        // A non-null buffer distinguishes execution from CUB's sizing query.
 27	        checked(cudaMalloc(&pointer_, bytes ? bytes : 1), "cudaMalloc");
 28	    }
 29	    DeviceBuffer(const DeviceBuffer&) = delete;
 30	    DeviceBuffer& operator=(const DeviceBuffer&) = delete;
 31	    ~DeviceBuffer() noexcept {
 32	        if (pointer_) {
 33	            const auto status = cudaFree(pointer_);
 34	            if (status != cudaSuccess)
 35	                std::fprintf(stderr, "CUDA cleanup during unwinding: %s\n", cudaGetErrorString(status));
 36	        }
 37	    }
 38	    void* get() const noexcept { return pointer_; }
 39	    void close() {
 40	        void* allocation = pointer_;
 41	        pointer_ = nullptr; // One free attempt, including when the runtime reports an error.
 42	        checked(cudaFree(allocation), "cudaFree");
 43	    }
 44	private:
 45	    void* pointer_ = nullptr;
 46	};
