 49	void cub_radix_sort(Values& values) {
 50	    if (values.size() > static_cast<std::size_t>(INT_MAX) ||
 51	        values.size() > std::numeric_limits<std::size_t>::max() / sizeof(Key))
 52	        throw std::length_error("cub_radix_sort size exceeds supported item/byte count");
 53	    int device = 0;
 54	    cudaDeviceProp properties{};
 55	    checked(cudaGetDevice(&device), "cudaGetDevice");
 56	    checked(cudaGetDeviceProperties(&properties, device), "cudaGetDeviceProperties");
 57	    if (values.size() < 2) return;
 58	
 59	    Values output(values.size());
 60	    const auto bytes = values.size() * sizeof(Key);
 61	    const int count = static_cast<int>(values.size());
 62	    DeviceBuffer input(bytes), sorted(bytes);
 63	    auto* in = static_cast<Key*>(input.get());
 64	    auto* out = static_cast<Key*>(sorted.get());
 65	    std::size_t workspace_bytes = 0;
 66	    checked(cub::DeviceRadixSort::SortKeys(nullptr, workspace_bytes, in, out, count, 0, 32),
 67	            "CUB SortKeys workspace query");
 68	    DeviceBuffer workspace(workspace_bytes);
 69	    checked(cudaMemcpy(in, values.data(), bytes, cudaMemcpyHostToDevice), "H2D cudaMemcpy");
 70	    checked(cub::DeviceRadixSort::SortKeys(workspace.get(), workspace_bytes, in, out, count, 0, 32),
 71	            "CUB SortKeys");
 72	    checked(cudaGetLastError(), "CUB launch status");
 73	    checked(cudaStreamSynchronize(nullptr), "CUB stream synchronize");
 74	    checked(cudaMemcpy(output.data(), out, bytes, cudaMemcpyDeviceToHost), "D2H cudaMemcpy");
 75	    workspace.close();
 76	    sorted.close();
 77	    input.close();
 78	    values.swap(output);
 79	}
